export function buildInvestingSchedule(startISO = null) {
  return buildScheduleFor(INVESTING_MODULES, startISO, INVESTING_META.cadenceDays);
}

export function investingProgressSummary(progress = {}) {
  return progressSummaryFor(INVESTING_MODULES, progress);
}

export function exportInvestingCurriculumMarkdown(startISO = null) {
  return exportCurriculumMarkdownFor({
    meta: INVESTING_META,
    modules: buildInvestingSchedule(startISO),
    sessionFlow: INVESTING_SESSION_FLOW,
  }, startISO);
}

/** Every Scripture reference this course cites, deduped — what the verse gate walks. */
export function investingRefs() {
  const seen = new Set();
  for (const m of INVESTING_MODULES) {
    for (const part of String((m.anchor && m.anchor.ref) || '').split(';')) {
      const ref = part.trim();
      if (ref) seen.add(ref);
    }
  }
  for (const part of String((INVESTING_META.wordFirst && INVESTING_META.wordFirst.ref) || '').split(';')) {
    const ref = part.trim();
    if (ref) seen.add(ref);
  }
  return [...seen];
}

